function [p_g, q_g, i_c] = mfun_gfl_standby_output(enable, p_g_in, q_g_in, i_c_in, fbk_in)
%MFUN_GFL_STANDBY_OUTPUT Block compute_standby_output of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the Simulink model, which adds its folder to the MATLAB
%   path. The parameters are the fields of the struct p (from the mask, [] as NaN).
fbk = gfl_feedbacks_unpack(fbk_in);
% References of compute_output, or while the gates are blocked, of
% compute_standby_output
if enable > 0
    p_g = p_g_in;
    q_g = q_g_in;
    i_c = i_c_in;
else
    p_g = 0.0;
    q_g = 0.0;
    i_c = [real(fbk.i_c); imag(fbk.i_c)];
end
end

function s = gfl_feedbacks_unpack(u)
%GFL_FEEDBACKS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c', complex(u(1), u(2)), ...
    'u_c', complex(u(3), u(4)), ...
    'u_g', u(5), ...
    'u_g_meas', complex(u(6), u(7)), ...
    'theta_c', u(8), ...
    'w_g', u(9), ...
    'w_c', u(10), ...
    'p_g', u(11), ...
    'q_g', u(12), ...
    'eps', u(13));
end
